\label{lst:1}
Let $F(\lambda, n)$ denote the set of fillings $\sigma: \lambda \rightarrow [n]$ satisfying
\begin{itemize}
\item $\sigma(u) \neq \sigma(v)$ whenever $u$ and $v$ attack each other, and
\item $\sigma$ is weakly increasing in rows, i.e. $\sigma(u) \leq \sigma(\textrm{r}(u)).$
\end{itemize}
We call such fillings \emph{Haglund-Haiman-Loehr-type fillings} or \emph{HHL} for short.

\label{whittaker}
Given a dominant weight $\lambda$ of size $n$, and $\sigma \in F(\lambda+\rho, n)$. We have \begin{equation*}
\sum_{(w,T) \in f^{-1}(\sigma)} (-1)^{\ell(wT)}t^{\frac{1}{2}(\ell(w)+\ell(wT)-|T|)}(t-1)^{|T|}=(-1)^{n-a_{0}+\ell(C)}t^{n-a_{0}+\emph{inv}(\sigma)}(1-t)^{\emph{des}(\sigma)}.
\end{equation*}
Where $C$ is the first column of $\sigma$, and $a_{0}$ is the unique entry missing from $C$.

Let $\rho$ be the partition $(n-1,\ldots,1)$. For any partition $\lambda$, we have
\begin{equation*}
\widetilde{W}_{\lambda}=\sum_{\sigma \in F(\lambda+\rho, n)}(-1)^{n-a_{0}+\ell(C)}t^{n-a_{0}+\emph{inv}(\sigma)}(1-t)^{\emph{des}(\sigma)}x^{\emph{ct}(\sigma)},
\end{equation*}
where $C$ is the first column of $\sigma$ and $a_{0}$ is the unique element absent from $C$.

\label{prop1}
Consider a permutation $w \in S_{n}$ and a number $b \in [n]\setminus \{a\}$, where $a:=w(1)$. Consider an integer $p$ such that $0\leq p < w^{-1}(b)-1$. Then we have 
\begin{equation} \label{eq:10}
\sum_{\substack{T:(w,T)\in \mathcal{A}(\overline{\Gamma}(1,p)) \\ wT(1)=b}} t^{N(w,T)}(1-t)^{|T|}=t^{N_{a,b}(w[2,p+1])}(1-t)^{1- \delta_{ab}}.
\end{equation}

\label{prop2} Consider two sequences $C_{1} \leq C_{2}$ of size $k$ and entries in $[n]$, where $\leq$ denotes the componentwise order. Also consider a permutation $w\in S_{n}$ such that $w[1,k]=C_{1}$. Then we have 
\begin{equation}\label{eq:2}
\sum_{\substack{T:(w,T)\in \mathcal{A}(\overline{\Gamma}(k)) \\ wT[1,k]=C_{2}}} t^{N(w,T)}(1-t)^{|T|}=t^{\ell(C_{2})-(\ell(C_{1})-\emph{inv}(C_{1}C_{2}))}(1-t)^{\emph{des}(C_{1}C_{2})}.
\end{equation}
Where $C_{1}C_{2}$ denotes the two column filling with left column $C_{1}$ and right column $C_{2}$.

Split $\overline{\Gamma}(k)$ as $\overline{\Gamma}_{1}(k)\ldots \overline{\Gamma}_{k}(k)$ by rows, so$$\overline{\Gamma}_{i}(k)=((i,k+1), (i,k+2), \ldots, (i,n)).$$ This splitting induces one for the subsequence $T$ of $\overline{\Gamma}(k)$, namely $T=T_{1}\ldots T_{k}$. For $i=0,\ldots, k$ define $w_{i}=wT_{1}\ldots T_{i}$, in particular $w_{0}=w$. So we can split the sum in (\ref{eq:2}) as a $k$-fold sum as follows
\begin{equation*}
\sum_{\substack{T_{1}:(w,T_{1})\in \mathcal{A}(\overline{\Gamma}_{1}(k)) \\ w_{0}T_{1}(1)=C_{2}(1)}}t^{N(w_{0},T_{1})}(1-t)^{|T_{1}|}\ldots \sum_{\substack{T_{k}:(w_{k-1},T_{k})\in A(\overline{\Gamma}_{k}(k)) \\ w_{k-1}T_{k}(k)=C_{2}(k)}}t^{N(w_{k-1},T_{k})}(1-t)^{|T_{k}|}
\end{equation*}
By Proposition \ref{prop1}, we have 
\begin{equation*}
\sum_{\substack{T_{i}:(w_{i-1},T_{i})\in \mathcal{A}(\overline{\Gamma}_{i}(k)) \\ w_{i-1}T_{i}(i)=C_{2}(i)}}t^{N(w_{i-1},T_{i})}(1-t)^{|T_{i}|}=t^{N_{C_{1}(i),C_{2}(i)}(C_{1}[i+1,k])}(1-t)^{1- \delta_{C_{1}(i)C_{2}(i)}}.
\end{equation*}
So we get $t^{e}(1-t)^{des(C_{1}C_{2})}$ where $$e=\sum_{i=1}^{k-1}N_{C_{1}(i),C_{2}(i)}(C_{1}[i+1,k]).$$
Clearly, $e$ is the number of ascents $(i,j)$ in $C_{1}$(meaning that $i<j$ and $C_{1}(i)<C_{1}(j)$) for which $C_{1}(j)<C_{2}(i)$. If $(i,j)$ is an ascent in $C_{1}$ not satisfying the previous condition, so $C_{1}(j)> C_{2}(i)$, then $(i,j)$ is an ascent in $C_{2}$ by the weakly increasing rows condition on fillings. The only ascents in $C_{2}$ which do not arise this way are counted by $\textrm{inv}(C_{1}C_{2})$. Therefore, $e=\binom{k}{2}-\ell(C_{1})-(\binom{k}{2}-\ell(C_{2})-\textrm{inv}(C_{1}C_{2}))=\ell(C_{2})-(\ell(C_{1})-\textrm{inv}(C_{1}C_{2}))$.

